--
-- Table structure for table `wp_ml_clinic_blocked_dates`
--

DROP TABLE IF EXISTS `wp_ml_clinic_blocked_dates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wp_ml_clinic_blocked_dates` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `blocked_date` date NOT NULL,
  `all_day` tinyint(1) NOT NULL DEFAULT 1,
  `start_time` time DEFAULT NULL,
  `end_time` time DEFAULT NULL,
  `reason` varchar(200) DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `blocked_date` (`blocked_date`),
  KEY `date_all_day` (`blocked_date`,`all_day`)
) ENGINE=InnoDB AUTO_INCREMENT=106 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

