  `chief_complaint` text DEFAULT NULL,
  `diagnosis` text DEFAULT NULL,
  `clinical_notes` text DEFAULT NULL,
  `treatment_plan` text DEFAULT NULL,
  `skin_type` varchar(50) DEFAULT NULL,
  `fitzpatrick_type` varchar(20) DEFAULT NULL,
  `skin_sensitivity` varchar(50) DEFAULT NULL,
  `oiliness_level` varchar(50) DEFAULT NULL,
  `pigmentation_notes` text DEFAULT NULL,
  `acne_severity` varchar(50) DEFAULT NULL,
  `scarring_notes` text DEFAULT NULL,
  `hair_loss_pattern` varchar(100) DEFAULT NULL,
  `hair_density` varchar(50) DEFAULT NULL,
  `scalp_condition` varchar(100) DEFAULT NULL,
  `hair_fall_duration` varchar(50) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `is_locked` tinyint(1) NOT NULL DEFAULT 0,
